wrap"><canvas id="revenueChart" aria-label="Son 30 gün satış grafiği"></canvas></div></article><article class="admin-panel"><h2>Sipariş durumları</h2><p class="muted">Tüm siparişlerin güncel dağılımı</p><div class="chart-canvas-wrap chart-doughnut-wrap"><canvas id="orderStatusChart" aria-label="Sipariş durumları grafiği"></canvas></div></article></div><div class="admin-panel"><div class="panel-heading"><h2>Son siparişler</h2><a href="<?= e(url('admin?section=orders')) ?>">Tüm siparişler →</a></div><div class="table-wrap"><table><thead><tr><th>Sipariş</th><th>Müşteri</th><th>Tutar</th><th>Ödeme</th><th>Durum</th><th>Tarih</th></tr></thead><tbody><?php foreach(($recentOrders??[]) as $o): ?><tr><td><strong><?= e($o['order_no']) ?></strong></td><td><?= e($o['customer_name']) ?></td><td><?= number_format((float)$o['total'],2,',','.') ?> ₺</td><td><span class="status"><?= e($o['payment_status']) ?></span></td><td><?= e($o['status']) ?></td><td><?= e(date('d.m.Y H:i',strtotime($o['created_at']))) ?></td></tr><?php endforeach; ?><?php if(empty($recentOrders)): ?><tr><td colspan="6" class="muted">Henüz sipariş bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></div><div class="admin-panel"><div class="panel-heading"><h2>En çok satan ürünler</h2><a href="<?= e(url('admin?section=products')) ?>">Ürünleri yönet →</a></div><div class="table-wrap"><table><thead><tr><th>Ürün</th><th>Satılan adet</th><th>Sipariş</th><th>Net satış</th></tr></thead><tbody><?php foreach(($bestSellingProducts??[]) as $product): ?><tr><td><strong><?= e($product['product_name']) ?></strong></td><td><?= number_format((int)$product['units_sold'],0,',','.') ?></td><td><?= number_format((int)$product['order_count'],0,',','.') ?></td><td><?= number_format((float)$product['net_sales'],2,',','.') ?> ₺</td></tr><?php endforeach; ?><?php if(empty($bestSellingProducts)): ?><tr><td colspan="4" class="muted">Henüz doğrulanmış satış verisi bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></div><div class="admin-panel"><div class="panel-heading"><div><h2>Demo mağaza içeriği</h2><p class="muted">6 kategori, 32 örnek ürün, ürün seçenekleri, 5 içerik sayfası, vitrin menüleri ve indirim kuponları. Demo içerikleri gerçek kod veya üyelik içermez.</p></div><div class="demo-actions"><form method="post" action="<?= e(url('admin?section=demo')) ?>" onsubmit="return confirm('Demo içerikleri mağazanıza eklensin mi? Mevcut içerikler silinmez.')"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="seed"><button type="submit">Demo içerikleri ekle</button></form><form method="post" action="<?= e(url('admin?section=demo')) ?>"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="refresh_showcase"><button type="submit">Oyun görselli vitrini yükle / yenile</button></form></div></div><p class="muted">Demo içeriklerini bir kez ekleyin. Vitrin yenileme işlemi ürün, sipariş veya mevcut sayfa kayıtlarını silmez.</p></div><div class="admin-panel"><h2>Kurulum modeli</h2><p><?= config('business_mode')==='multi_vendor'?'Multi Vendor · Çok satıcılı pazar yeri':'Single Vendor · Tek işletmeli mağaza' ?></p><p class="muted">İçerikler veritabanından yönetilir.</p></div><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script><script>(function(){if(typeof Chart==='undefined')return;const revenue=<?= json_encode($revenueChart??[],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;const statuses=<?= json_encode($orderStatusChart??[],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;const money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(v);const line=document.getElementById('revenueChart');if(line)new Chart(line,{type:'line',data:{labels:revenue.map(x=>x.day),datasets:[{label:'Ciro',data:revenue.map(x=>x.revenue),borderColor:'#635bff',backgroundColor:'rgba(99,91,255,.12)',fill:true,tension:.35,yAxisID:'y'},{label:'Sipariş',data:revenue.map(x=>x.orders),borderColor:'#10a37f',backgroundColor:'#10a37f',tension:.3,yAxisID:'y1'}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{tooltip:{callbacks:{label:c=>c.dataset.label==='Ciro'?c.dataset.label+': '+money(c.parsed.y):c.dataset.label+': '+c.parsed.y}}},scales:{y:{beginAtZero:true,ticks:{callback:v=>money(v)}},y1:{beginAtZero:true,position:'right',grid:{drawOnChartArea:false},ticks:{precision:0}}}}});const doughnut=document.getElementById('orderStatusChart');if(doughnut)new Chart(doughnut,{type:'doughnut',data:{labels:statuses.map(x=>x.status),datasets:[{data:statuses.map(x=>Number(x.total)),backgroundColor:['#635bff','#10a37f','#f59e0b','#ef4444','#64748b','#06b6d4','#a855f7'],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}});})();</script>
