n-list"><?php foreach(($refundRows??[]) as $r): ?><article class="seller-admin-card"><div><strong><?= e($r['order_no']) ?> · <?= number_format((float)$r['total'],2,',','.') ?> ₺</strong><span class="account-status"><?= e($r['status']) ?></span><p><?= e($r['customer_name']) ?> · <?= e($r['customer_email']) ?> · Ödeme: <?= e($r['payment_status']) ?></p><p><?= nl2br(e($r['reason'])) ?></p><small><?= e($r['requested_at']) ?></small><?php if(!empty($r['admin_note'])): ?><p>Yönetici notu: <?= e($r['admin_note']) ?></p><?php endif; ?></div><?php if(in_array($r['status'],['requested','approved'],true)): ?><form method="post" class="ticket-admin-form"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><label>Yönetici notu<textarea name="admin_note" rows="2"><?= e($r['admin_note']??'') ?></textarea></label><?php if($r['status']==='requested'): ?><button name="decision" value="approved">Onayla</button><button class="link-danger" name="decision" value="rejected">Reddet</button><?php else: ?><button name="decision" value="processed" onclick="return confirm('Ödeme sağlayıcısında iade işlemi tamamlandı mı?')">İade tamamlandı olarak kaydet</button><?php endif; ?></form><?php endif; ?></article><?php endforeach; ?><?php if(empty($refundRows)): ?><div class="admin-panel">Henüz iade talebi yok.</div><?php endif; ?></div>
<?php elseif($resource==='payments'): ?><div class="page-head"><h1>Ödeme sağlayıcıları</h1><p>PayTR ve iyzico entegrasyon bilgileri. Gizli anahtarlar veritabanında şifreli tutulur.</p></div><form class="admin-form" method="post"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><h2>PayTR iFrame API</h2><p class="muted">PayTR mağaza panelindeki Bildirim URL alanına şu adresi girin: <strong><?= e(absolute_url("payment/paytr-callback")) ?></strong></p><label><input type="checkbox" name="paytr_enabled" value="1" <?= ($paymentSettings['paytr_enabled']??'')==='1'?'checked':'' ?>> PayTR etkin</label><label><input type="checkbox" name="paytr_sandbox" value="1" <?= ($paymentSettings['paytr_sandbox']??'')==='1'?'checked':'' ?>> Test modu</label><label>Mağaza numarası<input name="paytr_merchant_id" value="<?= e($paymentSettings['paytr_merchant_id']??'') ?>"></label><label>Mağaza anahtarı<input type="password" name="paytr_merchant_key" placeholder="Boş bırakırsanız mevcut anahtar korunur"></label><label>Mağaza gizli anahtarı<input type="password" name="paytr_merchant_salt" placeholder="Boş bırakırsanız mevcut anahtar korunur"></label><hr><h2>iyzico Checkout Form</h2><label><input type="checkbox" name="iyzico_enabled" value="1" <?= ($paymentSettings['iyzico_enabled']??'')==='1'?'checked':'' ?>> iyzico etkin</label><label><input type="checkbox" name="iyzico_sandbox" value="1" <?= ($paymentSettings['iyzico_sandbox']??'')==='1'?'checked':'' ?>> Test modu</label><label>API anahtarı<input type="password" name="iyzico_api_key" placeholder="Boş bırakırsanız mevcut anahtar korunur"></label><label>Gizli anahtar<input type="password" name="iyzico_secret_key" placeholder="Boş bırakırsanız mevcut anahtar korunur"></label><button type="submit">Ayarları kaydet</button></form><?php elseif($resource==='inventory'): ?><div class="page-head"><div><p class="eyebrow">DİJİTAL TESLİMAT</p><h1>E-pin stok yönetimi</h1><p>Kodlar veritabanın