ame="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><?php foreach($meta[$resource]['fields'] as $field=>$label): ?><label><?= e($label) ?><?php if(in_array($field,['description','content','short_description'],true)): ?><textarea name="<?= e($field) ?>" rows="<?= $field==='content'?8:3 ?>"><?= e($edit[$field]??'') ?></textarea><?php elseif($field==='category_id'): ?><select name="category_id"><option value="">Kategori seçin</option><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (string)($edit['category_id']??'')===(string)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select><?php elseif($field==='product_id'&&$resource==='variants'): ?><select name="product_id" required><option value="">Ana ürün seçin</option><?php foreach(($variantProducts??[]) as $vp): ?><option value="<?= (int)$vp['id'] ?>" <?= (string)($edit['product_id']??'')===(string)$vp['id']?'selected':'' ?>><?= e($vp['name']) ?></option><?php endforeach; ?></select><?php elseif($field==='discount_type'): ?><select name="discount_type"><option value="percent" <?= ($edit[$field]??'percent')==='percent'?'selected':'' ?>>Yüzde (%)</option><option value="fixed" <?= ($edit[$field]??'')==='fixed'?'selected':'' ?>>Sabit tutar (₺)</option></select><?php elseif(in_array($field,['starts_at','expires_at'],true)): ?><input type="datetime-local" name="<?= e($field) ?>" value="<?= e(!empty($edit[$field])?str_replace(' ','T',substr((string)$edit[$field],0,16)):'') ?>"><?php elseif($field==='location'&&$resource==='menus'): ?><select name="location"><option value="header" <?= ($edit[$field]??'header')==='header'?'selected':'' ?>>Üst menü</option><option value="footer" <?= ($edit[$field]??'')==='footer'?'selected':'' ?>>Alt menü</option></select><?php elseif($field==='menu_type'&&$resource==='menus'): ?><select name="menu_type"><option value="link" <?