ble><thead><tr><th>#</th><th>Başlık</th><th>Durum</th><th>İşlem</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= (int)$row['id'] ?></td><td><strong><?= e($row['name']??$row['title']??$row['code']??$row['sku']??'') ?></strong><small><?= e($row['product_name']??$row['slug']??$row['url']??'') ?></small></td><td><span class="status"><?= e($row['status']??'') ?></span></td><td class="actions"><a href="<?= e(url('admin?section='.$resource.'&edit='.(int)$row['id'])) ?>">Düzenle</a><form method="post" onsubmit="return confirm('Bu kayıt silinsin mi?')"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="link-danger" type="submit">Sil</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4" class="muted">Henüz kayıt eklenmemiş.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?>
